SELECT asmt.asmt_sn, asmt.asmt_id, asmt.asmt_prgrs_stts_cd, asmt.asmt_nm, asmt.flfmt_bgng_dt, asmt.flfmt_end_dt, asmt.inst_id, inst.inst_nm, dept.dept_nm, asmt.rgtr_id, asmt.del_yn, asmt.reg_dt, asmt.mdfr_id, asmt.mdfcn_dt, COALESCE(meta_cnt.meta_analysis_count, 0) AS meta_analysis_count FROM kids_own.TB_CM_M_ASMT asmt LEFT JOIN kids_own.TB_PP_M_INST inst ON asmt.inst_id = inst.brno LEFT JOIN kids_own.TB_PP_M_DEPT_INFO dept ON asmt.inst_id = dept.dept_no LEFT JOIN ( SELECT m.asmt_sn, COUNT(*) AS meta_analysis_count FROM kids_own.TB_CM_E_ASMT_META m WHERE m.rslt_group_cd = '04' AND (m.del_yn IS NULL OR m.del_yn = 'N') GROUP BY m.asmt_sn ) meta_cnt ON meta_cnt.asmt_sn = asmt.asmt_sn
AND (asmt.del_yn IS NULL OR asmt.del_yn = 'N')
AND asmt.asmt_prgrs_stts_cd = #{request.progressStatus}
AND asmt.asmt_nm LIKE CONCAT('%', #{request.keyword}, '%')
AND asmt.asmt_artcl_dtl_cn LIKE CONCAT('%', #{request.keyword}, '%')
AND (asmt.asmt_nm LIKE CONCAT('%', #{request.keyword}, '%') OR asmt.asmt_artcl_dtl_cn LIKE CONCAT('%', #{request.keyword}, '%'))
AND asmt.flfmt_bgng_dt <= #{request.searchEndDate} AND asmt.flfmt_end_dt >= #{request.searchStartDate}
AND asmt.flfmt_end_dt >= #{request.searchStartDate}
AND asmt.flfmt_bgng_dt <= #{request.searchEndDate}
AND asmt.inst_id = #{instId}
ORDER BY asmt.reg_dt DESC LIMIT #{request.limit} OFFSET #{request.offset};

SELECT DISTINCT asmt.asmt_sn, asmt.asmt_id, asmt.asmt_prgrs_stts_cd, asmt.asmt_nm, asmt.flfmt_bgng_dt, asmt.flfmt_end_dt, asmt.inst_id, inst.inst_nm, dept.dept_nm, asmt.rgtr_id, asmt.del_yn, asmt.reg_dt, asmt.mdfr_id, asmt.mdfcn_dt, COALESCE(meta_cnt.meta_analysis_count, 0) AS meta_analysis_count, prcp.ptcp_prgrs_stts_cd, prcp.uld_type_cd AS uld_type_cd FROM kids_own.TB_CM_M_ASMT asmt INNER JOIN kids_own.TB_CM_M_ASMT_PRCP prcp ON asmt.asmt_sn = prcp.asmt_sn LEFT JOIN kids_own.TB_PP_M_INST inst ON asmt.inst_id = inst.brno LEFT JOIN kids_own.TB_PP_M_DEPT_INFO dept ON asmt.inst_id = dept.dept_no LEFT JOIN ( SELECT m.asmt_sn, COUNT(*) AS meta_analysis_count FROM kids_own.TB_CM_E_ASMT_META m WHERE m.rslt_group_cd = '04' AND (m.del_yn IS NULL OR m.del_yn = 'N') GROUP BY m.asmt_sn ) meta_cnt ON meta_cnt.asmt_sn = asmt.asmt_sn
AND (asmt.del_yn IS NULL OR asmt.del_yn = 'N') AND (prcp.del_yn IS NULL OR prcp.del_yn = 'N') AND prcp.inst_id = #{instBrno}
AND prcp.ptcp_prgrs_stts_cd = #{request.progressStatus}
AND asmt.asmt_nm LIKE CONCAT('%', #{request.keyword}, '%')
AND asmt.asmt_artcl_dtl_cn LIKE CONCAT('%', #{request.keyword}, '%')
AND (asmt.asmt_nm LIKE CONCAT('%', #{request.keyword}, '%') OR asmt.asmt_artcl_dtl_cn LIKE CONCAT('%', #{request.keyword}, '%'))
AND asmt.flfmt_bgng_dt <= #{request.searchEndDate} AND asmt.flfmt_end_dt >= #{request.searchStartDate}
AND asmt.flfmt_end_dt >= #{request.searchStartDate}
AND asmt.flfmt_bgng_dt <= #{request.searchEndDate}
ORDER BY asmt.reg_dt DESC LIMIT #{request.limit} OFFSET #{request.offset};

