SELECT COUNT(*)
FROM kids_own.TB_CM_M_ASMT
WHERE EXTRACT(YEAR FROM reg_dt) = #{year}
AND inst_id = #{instId}
AND (del_yn IS NULL OR del_yn = 'N')

SELECT meta.asmt_meta_rslt_sn, meta.asmt_sn, meta.asmt_meta_rslt_cn, meta.asmt_meta_rslt_stts_cd, meta.rslt_noti_dt, meta.rslt_group_cd, meta.del_yn, meta.rgtr_id, meta.reg_dt, meta.mdfr_id, meta.mdfcn_dt FROM kids_own.TB_CM_E_ASMT_META meta
INNER JOIN kids_own.TB_PP_M_MBR_INFO mbr ON meta.rgtr_id = mbr.mbr_no INNER JOIN kids_own.TB_PP_M_EXPRT_INFO exprt ON mbr.mbr_no = exprt.mbr_no
WHERE meta.asmt_sn = #{asmtSn} AND (meta.del_yn IS NULL OR meta.del_yn = 'N')
AND exprt.brno = #{instId}
AND meta.rslt_group_cd = #{rsltGroupStcd}
ORDER BY meta.reg_dt DESC

SELECT opnn.opnn_intg_rslt_sn, opnn.asmt_meta_rslt_sn as opnn_asmt_meta_rslt_sn, opnn.asmt_sn as opnn_asmt_sn, opnn.inst_id as opnn_inst_id, opnn.opnn_intg_dmnd_cn, opnn.utlz_agre_se_cd as opnn_utlz_agre_se_cd, opnn.asmt_opnn_stts_cd as opnn_asmt_opnn_stts_cd, opnn.del_yn as opnn_del_yn, opnn.rgtr_id as opnn_rgtr_id, opnn.reg_dt as opnn_reg_dt, opnn.mdfr_id as opnn_mdfr_id, opnn.mdfcn_dt as opnn_mdfcn_dt, mbr.mbr_no as opnn_mbr_no, mbr.encpt_mbr_flnm AS opnn_mbr_encpt_flnm, emp.emp_nm AS opnn_emp_nm, exprt.brno as opnn_brno, exprt.exprt_hdof_yn as opnn_exprt_hdof_yn, inst.inst_nm as opnn_inst_nm FROM kids_own.TB_CM_E_OPNN opnn LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON opnn.mdfr_id = mbr.mbr_no LEFT JOIN kids_own.TB_PP_M_EMP_INFO emp ON opnn.mdfr_id = emp.emp_no LEFT JOIN kids_own.TB_PP_M_EXPRT_INFO exprt ON mbr.mbr_no = exprt.mbr_no LEFT JOIN kids_own.TB_PP_M_INST inst ON exprt.brno = inst.brno WHERE opnn.asmt_meta_rslt_sn = #{asmtMetaRsltSn}
AND opnn.inst_id = #{instId}
AND (opnn.del_yn IS NULL OR opnn.del_yn = 'N') ORDER BY opnn.reg_dt DESC LIMIT 1

SELECT meta.asmt_meta_rslt_sn, meta.asmt_sn, meta.asmt_meta_rslt_cn, meta.asmt_meta_rslt_stts_cd, meta.rslt_group_cd, meta.del_yn, meta.rgtr_id, meta.reg_dt, meta.mdfr_id, meta.mdfcn_dt, meta.rslt_noti_dt, mbr.encpt_mbr_flnm AS mbr_encpt_flnm, emp.emp_nm AS emp_nm FROM kids_own.TB_CM_E_ASMT_META meta LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON meta.rgtr_id = mbr.mbr_no LEFT JOIN kids_own.TB_PP_M_EMP_INFO emp ON meta.rgtr_id = emp.emp_no WHERE meta.asmt_sn = #{asmtSn} AND (meta.del_yn IS NULL OR meta.del_yn = 'N')
AND meta.rslt_group_cd = #{rsltGroupStcd}
ORDER BY meta.reg_dt DESC LIMIT 1

