SELECT COUNT(*)
FROM kids_own.TB_CM_E_ASMT_META meta

  INNER JOIN kids_own.TB_PP_M_MBR_INFO mbr ON meta.rgtr_id = mbr.mbr_no
  INNER JOIN kids_own.TB_PP_M_EXPRT_INFO exprt ON mbr.mbr_no = exprt.mbr_no

WHERE meta.asmt_sn = #{asmtSn}
AND meta.rslt_group_cd = #{rsltGroupStcd}
AND (meta.del_yn IS NULL OR meta.del_yn = 'N')
AND meta.asmt_meta_rslt_stts_cd IN ('01', '02', '03')

  AND exprt.brno = #{instId}

SELECT COUNT(*)
FROM kids_own.TB_CM_E_OPNN
WHERE asmt_meta_rslt_sn = #{asmtMetaRsltSn}
AND inst_id = #{instId}
AND (del_yn IS NULL OR del_yn = 'N')

SELECT opnn.opnn_intg_rslt_sn AS opnnIntgRsltSn, opnn.asmt_meta_rslt_sn AS asmtMetaRsltSn, opnn.asmt_sn AS asmtSn, opnn.inst_id AS instId, opnn.opnn_intg_dmnd_cn AS opnnIntgDmndCn, opnn.utlz_agre_se_cd AS utlzAgreSeCd, opnn.asmt_opnn_stts_cd AS asmtOpnnSttsCd, opnn.del_yn AS delYn, opnn.rgtr_id AS rgtrId, opnn.reg_dt AS regDt, opnn.mdfr_id AS mdfrId, opnn.mdfcn_dt AS mdfcnDt, mbr.mbr_no AS mbrId, mbr.encpt_mbr_flnm AS mbr_encpt_flnm, emp.emp_nm AS emp_nm, exprt.brno AS brno, exprt.exprt_hdof_yn AS exprtHdofYn, inst.inst_nm AS instNm FROM kids_own.TB_CM_E_OPNN opnn LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON opnn.rgtr_id = mbr.mbr_no LEFT JOIN kids_own.TB_PP_M_EMP_INFO emp ON opnn.rgtr_id = emp.emp_no LEFT JOIN kids_own.TB_PP_M_EXPRT_INFO exprt ON mbr.mbr_no = exprt.mbr_no LEFT JOIN kids_own.TB_PP_M_INST inst ON opnn.inst_id = inst.brno INNER JOIN kids_own.TB_CM_E_ASMT_META meta ON opnn.asmt_meta_rslt_sn = meta.asmt_meta_rslt_sn AND opnn.asmt_sn = meta.asmt_sn WHERE opnn.asmt_sn = #{asmtSn} AND opnn.asmt_meta_rslt_sn = #{asmtMetaRsltSn}
AND opnn.inst_id = #{instId}
AND meta.rslt_group_cd = #{rsltGroupStcd}
AND (opnn.del_yn IS NULL OR opnn.del_yn = 'N') ORDER BY opnn.reg_dt ASC

SELECT prcp.asmt_sn, prcp.inst_id, inst.inst_nm, opnn.opnn_intg_rslt_sn, opnn.asmt_meta_rslt_sn, meta.rslt_group_cd, opnn.opnn_intg_dmnd_cn, opnn.utlz_agre_se_cd, opnn.asmt_opnn_stts_cd AS asmt_opnn_stts_cd, opnn.rgtr_id, opnn.reg_dt, opnn.mdfr_id, opnn.mdfcn_dt, mbr.encpt_mbr_flnm AS mdfr_nm, NULL AS uld_inst_prgrs_stts_cd, prcp.uld_type_cd AS uld_type_cd FROM kids_own.TB_CM_E_OPNN opnn INNER JOIN kids_own.TB_CM_M_ASMT_PRCP prcp ON prcp.asmt_sn = opnn.asmt_sn AND prcp.inst_id = opnn.inst_id AND (prcp.del_yn IS NULL OR prcp.del_yn = 'N') INNER JOIN kids_own.TB_CM_E_ASMT_META meta ON opnn.asmt_meta_rslt_sn = meta.asmt_meta_rslt_sn AND opnn.asmt_sn = meta.asmt_sn LEFT JOIN kids_own.TB_PP_M_INST inst ON prcp.inst_id = inst.brno LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON opnn.mdfr_id = mbr.mbr_no WHERE opnn.asmt_sn = #{asmtSn}
AND (opnn.asmt_opnn_stts_cd = '08' OR opnn.asmt_opnn_stts_cd = '10')
AND opnn.utlz_agre_se_cd = #{utlzAgreSeCd}
AND opnn.inst_id = #{instId}
AND (opnn.del_yn IS NULL OR opnn.del_yn = 'N') ORDER BY opnn.reg_dt DESC

SELECT prcp.asmt_sn, prcp.inst_id, inst.inst_nm, opnn.opnn_intg_rslt_sn, opnn.asmt_meta_rslt_sn, meta.rslt_group_cd, opnn.opnn_intg_dmnd_cn, opnn.utlz_agre_se_cd, opnn.asmt_opnn_stts_cd AS asmt_opnn_stts_cd, opnn.rgtr_id, opnn.reg_dt, opnn.mdfr_id, opnn.mdfcn_dt, mbr.encpt_mbr_flnm AS mdfr_nm, NULL AS uld_inst_prgrs_stts_cd, prcp.uld_type_cd AS uld_type_cd FROM kids_own.TB_CM_E_OPNN opnn INNER JOIN kids_own.TB_CM_M_ASMT_PRCP prcp ON prcp.asmt_sn = opnn.asmt_sn AND prcp.inst_id = opnn.inst_id AND (prcp.del_yn IS NULL OR prcp.del_yn = 'N') INNER JOIN kids_own.TB_CM_E_ASMT_META meta ON opnn.asmt_meta_rslt_sn = meta.asmt_meta_rslt_sn AND opnn.asmt_sn = meta.asmt_sn AND meta.rslt_group_cd = '04' LEFT JOIN kids_own.TB_PP_M_INST inst ON prcp.inst_id = inst.brno LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON opnn.mdfr_id = mbr.mbr_no WHERE opnn.asmt_sn = #{asmtSn} AND opnn.asmt_opnn_stts_cd = #{asmtOpnnSttsCd}
AND opnn.inst_id = #{instId}
AND (opnn.del_yn IS NULL OR opnn.del_yn = 'N') ORDER BY opnn.reg_dt DESC

SELECT opnn.asmt_sn, opnn.inst_id, inst.inst_nm, opnn.opnn_intg_rslt_sn, opnn.asmt_meta_rslt_sn, meta.rslt_group_cd, opnn.opnn_intg_dmnd_cn, opnn.utlz_agre_se_cd, opnn.rgtr_id, opnn.reg_dt, mbr.encpt_mbr_flnm AS mdfr_nm, opnn.mdfr_id, opnn.mdfcn_dt, NULL AS uld_inst_prgrs_stts_cd, NULL AS uld_type_cd, opnn.asmt_opnn_stts_cd AS asmt_opnn_stts_cd FROM kids_own.TB_CM_E_OPNN opnn INNER JOIN kids_own.TB_CM_E_ASMT_META meta ON opnn.asmt_meta_rslt_sn = meta.asmt_meta_rslt_sn AND opnn.asmt_sn = meta.asmt_sn LEFT JOIN kids_own.TB_PP_M_INST inst ON opnn.inst_id = inst.brno LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON opnn.mdfr_id = mbr.mbr_no WHERE opnn.asmt_sn = #{asmtSn} AND opnn.asmt_meta_rslt_sn = #{asmtMetaRsltSn}
AND opnn.utlz_agre_se_cd = #{utlzAgreSeCd}
AND (opnn.del_yn IS NULL OR opnn.del_yn = 'N')
AND opnn.inst_id IN
#{instId}
ORDER BY opnn.reg_dt DESC

SELECT meta.asmt_meta_rslt_sn, meta.asmt_sn, meta.asmt_meta_rslt_cn, meta.asmt_meta_rslt_stts_cd, meta.rslt_noti_dt, meta.rslt_group_cd, meta.del_yn, meta.rgtr_id, meta.reg_dt, meta.mdfr_id, meta.mdfcn_dt FROM ( SELECT m.asmt_meta_rslt_sn, m.asmt_sn, m.asmt_meta_rslt_cn, m.asmt_meta_rslt_stts_cd, m.rslt_noti_dt, m.rslt_group_cd, m.del_yn, m.rgtr_id, m.reg_dt, m.mdfr_id, m.mdfcn_dt, ROW_NUMBER() OVER (PARTITION BY m.asmt_sn ORDER BY m.reg_dt DESC) AS rn FROM kids_own.TB_CM_E_ASMT_META m WHERE (m.del_yn IS NULL OR m.del_yn = 'N') AND m.rslt_group_cd = #{rsltGroupStcd} AND m.asmt_sn IN
#{asmtSn}
) meta WHERE meta.rn = 1

SELECT m1.asmt_meta_rslt_sn, m1.asmt_sn, m1.asmt_meta_rslt_cn, m1.asmt_meta_rslt_stts_cd, m1.rslt_noti_dt, m1.rslt_group_cd, m1.del_yn, m1.rgtr_id, m1.reg_dt, m1.mdfr_id, m1.mdfcn_dt FROM kids_own.TB_CM_E_ASMT_META m1 LEFT JOIN kids_own.TB_PP_M_MBR_INFO mbr ON m1.rgtr_id = mbr.mbr_no LEFT JOIN kids_own.TB_PP_M_EXPRT_INFO exprt ON mbr.mbr_no = exprt.mbr_no INNER JOIN ( SELECT m.asmt_sn, e.brno, MAX(m.reg_dt) AS max_reg_dt FROM kids_own.TB_CM_E_ASMT_META m LEFT JOIN kids_own.TB_PP_M_MBR_INFO mb ON m.rgtr_id = mb.mbr_no LEFT JOIN kids_own.TB_PP_M_EXPRT_INFO e ON mb.mbr_no = e.mbr_no WHERE (m.del_yn IS NULL OR m.del_yn = 'N') AND m.rslt_group_cd = '03' AND m.asmt_sn IN
#{asmtSn}
GROUP BY m.asmt_sn, e.brno ) m2 ON m1.asmt_sn = m2.asmt_sn AND m1.reg_dt = m2.max_reg_dt AND (exprt.brno = m2.brno OR (exprt.brno IS NULL AND m2.brno IS NULL)) WHERE (m1.del_yn IS NULL OR m1.del_yn = 'N') AND m1.rslt_group_cd = '03' AND m1.asmt_sn IN
#{asmtSn}

