SET asmt_user_flnm = #{asmtUserFlnm},
    asmt_user_ip_addr = #{asmtUserIpAddr},
    asmt_user_srvc_no = #{asmtUserSrvcNo},
    user_se_cd = #{userSeCd},
    mdfr_id = #{mdfrId},
    mdfcn_dt = COALESCE(#{mdfcnDt}, NOW())

  , enpswd = #{enpswd}


  , asmt_lnkg_schm_nm = #{asmtAnalysisSchema}

WHERE asmt_user_info_sn = #{asmtUserInfoSn}

UPDATE kids_own.TB_CM_M_ASMT_CMNT
SET cmnt_dtl_cn = #{cmntDtlCn},
mdfr_id = #{mdfrId},
mdfcn_dt = #{mdfcnDt}
WHERE asmt_cmnt_sn = #{asmtCmntSn}
AND (del_yn IS NULL OR del_yn = 'N')

mapper.select:
SELECT COALESCE(MAX(cmnt_ans_sn), 0) + 1
FROM kids_own.TB_CM_M_ASMT_CMNT
WHERE asmt_sn = #{asmtSn}
AND (del_yn IS NULL OR del_yn = 'N')
AND (
(#{orgnlUpCmntAnsSn,jdbcType=NUMERIC} IS NULL AND orgnl_up_cmnt_ans_sn IS NULL)
OR orgnl_up_cmnt_ans_sn = #{orgnlUpCmntAnsSn,jdbcType=NUMERIC}
)

SELECT emp_no AS empNo, emp_nm AS empNm, dept_no AS deptNo FROM kids_own.tb_pp_m_emp_info WHERE dept_no IN
#{d}
ORDER BY dept_no, emp_no

SELECT emp_no AS empNo, emp_nm AS empNm, dept_no AS deptNo, encpt_emp_telno AS encptEmpTelno, encpt_emp_eml_nm AS encptEmpEmlNm, rgtr_id AS rgtrId, reg_dt AS regDt, mdfr_id AS mdfrId, mdfcn_dt AS mdfcnDt FROM kids_own.tb_pp_m_emp_info WHERE emp_no IN
#{e}
ORDER BY emp_no

SELECT DISTINCT p.person_id AS personId, op.inst_task_sn AS instTaskSn, p.person_source_value AS patid
FROM kids_link_own.person p
INNER JOIN kids_link_own.observation_period op ON op.person_id = p.person_id AND op.inst_task_sn = p.inst_task_sn
WHERE op.observation_period_start_date <= #{endDate}
  AND op.observation_period_end_date >= #{startDate}
  AND p.gender_concept_id = #{genderConceptId}
  AND op.inst_task_sn IN

    #{inst}
